use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.today();
    let rendered = signals.map(|s| match s {
        harbor.signal.Calm => "calm",
        harbor.signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
        harbor.signal.Fog(density) => "fog:".concat(other: density),
    });
    rendered.join(sep: ";")
}

use harbor.signal;

fn render_signal(sig: harbor.signal.Signal) -> String {
    match sig {
        harbor.signal.Calm => "calm",
        harbor.signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
        harbor.signal.Fog(density) => "fog:".concat(other: density),
    }
}

pub fn entries() -> String {
    let signals = harbor.signal.signals();
    var result = "";
    var i = 0;
    while i < signals.len() {
        let rendered = render_signal(sig: signals.get(index: i)?);
        if i == 0 {
            result = rendered;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
        i = i + 1;
    }
    result
}

