use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var i = 0;
    while true {
        match board.get(index: i) {
            Some(dish) => {
                if i > 0 {
                    io.write(text: ";")?;
                }
                galley.kitchen.serve(dish: dish, io: io)?;
                i = i + 1;
            }
            None => break,
        }
    }
    return Ok(unit);
}

