use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = herd.lineup();
    var entries: List<String> = [];

    for pony in lineup {
        let fed = herd.feed(pony: pony, scoops: 3);
        let entry = ledger.render(pony: fed);
