use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;

    while i < lineup.len() {
        let pony = lineup.get(index: i)?;
        let fed = stable.herd.feed(pony: pony, scoops: 3);
        let entry = stable.ledger.render(pony: fed);
        entries.push(item: entry);
        i = i + 1;
    }

    let output = entries.join(sep: ",");
    io.write(text: output)?;
    return Ok(unit);
}

use mill.stock;
use mill.rules;

fn lines() -> String {
    let inventory = stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < inventory.len() {
        let plank = inventory.get(index: i)?;
        if rules.should_keep(plank: plank) {
            let label = rules.render_label(plank: plank);
            labels.push(item: label);
        }
        i = i + 1;
    }
    return labels.join(sep: ",");
}

pub fn lines() -> String {
    let inventory = mill.stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < inventory.len() {
        let maybe_plank = inventory.get(index: i);
        i = i + 1;
        match maybe_plank {
            Some(plank) => {
                if mill.rules.should_keep(plank: plank) {
                    let label = mill.rules.render_label(plank: plank);
                    labels.push(item: label);
                }
            },
            None => {},
        };
    }
    labels.join(sep: ",")
}

use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = match frames.get(index: i) {
            Some(f) => f,
            None => break,
        };
        let decoded = feed.decode(frame: frame);
        let value = match decoded {
            Some(v) => v,
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
    feed.emit(total: total, io: io)?;
    return Ok(unit);
}
